            '      camera.top = viewSize; camera.bottom = -viewSize;\n',
            '    } else {\n',
            '      camera.aspect = w / h;\n',
            '    }\n',
            '    camera.updateProjectionMatrix();\n',
            '  }\n',
            '  function updateCameraPosition() {\n',
